    q16314: { h: "938ea3840a3b", text: "A diagnostic lab means a shift of the morning rush in the queue of samples: could you bear the rush of samples?" },
    q16315: { h: "d7fe7ee14f25", text: "Hospital supply means running with a list on rounds of the warehouse: would you like the run of the warehouse?" },
    q16316: { h: "2ab059097dfb", text: "The edge of surgical tools means a table of minute grinding: would you enjoy the table of the edge?" },
    q16317: { h: "6a1d28fe303c", text: "A hospital ward means a night shift of rounds on your feet: could you bear the night on the ward?" },
    q16318: { h: "8d76792593cc", text: "A telemedicine desk means sitting on screen calls without a break: would you like sitting on calls?" },
    q16319: { h: "4662982d9fe2", text: "Medical tourism means coordinating on the run between hospital and hotel: would you enjoy coordinating on the run?" },
    q16320: { h: "65cff16c4e51", text: "The dental chair means a shift of fine handwork with a bent neck: could you bear the bent neck?" },
    q16321: { h: "01fc3d0b6e3d", text: "Eye testing means an eye on the instrument in a dark room: would you like the eye in the dark?" },
    q16322: { h: "b9dd9276abbe", text: "Counselling means listening while seated and demands patience of mind: would you enjoy the patience of listening?" },
    q16323: { h: "8ee78f9feadf", text: "Service to the elderly means gentle strength in lifting and supporting: would you like the strength of support?" },
    q16324: { h: "2674b201e3e4", text: "Home nursing means rounds from home to home, on time: would you enjoy the rounds of homes?" },
    q16325: { h: "e35142418566", text: "An ambulance means a dash with the siren and a decision every moment: would you like the dash with the siren?" },
    q16326: { h: "1a26418f79df", text: "A blood bank means counting and checking the cold racks: would you enjoy checking the racks?" },
    q16327: { h: "d16ca332cf62", text: "A farm biotech lab means sitting at the repetition of the pipette: would you like sitting with the pipette?" },
    q16328: { h: "cdd0a3b32f48", text: "Industrial biotech means a shift of sampling the tanks: would you enjoy sampling the tanks?" },
    q16329: { h: "79c42e603ba2", text: "Marine biotech means a wet lab in salty air: would you like the wet lab?" },
    q16330: { h: "556b7c3f97d1", text: "A tissue lab means a constant eye at the microscope: would you enjoy the eye at the microscope?" },
    q16331: { h: "3dcd141e89c7", text: "A gene lab means steady handling of samples in the ice box: would you like steadiness with ice?" },
    q16332: { h: "57c3d7942bfd", text: "A DNA kit line means repetition in labelling tubes: would you enjoy the repetition of tubes?" },
    q16333: { h: "55b8a2c14c61", text: "A bio-pesticide unit means the smell of filtering solution: could you bear filtering the solution?" },
    q16334: { h: "25e54796c73f", text: "Earthworm compost means the hard work of turning damp beds: would you like turning the beds?" },
    q16335: { h: "07fb335854b6", text: "Cell storage means careful hands with liquid nitrogen: would you enjoy the hands on nitrogen?" },
    q16336: { h: "808227f644db", text: "A stem-cell lab means long steady work in the room suit: would you like steady work in the room?" },
    q16337: { h: "a043394d977b", text: "Animal medicine rounds mean walking with a bag in village dust: would you enjoy walking the rounds?" },
    q16338: { h: "6e4177963a82", text: "A medical waste vehicle means careful rounds lifting bins: could you bear the rounds of bins?" },
    q17257: { h: "a17aced4e505", text: "Without the test report, a batch of medicine is held back from release: could you bear the hold on a batch?" },
    q17258: { h: "0dc4ad81e028", text: "API approval takes years, audit after audit: would you count the years of audits?" },
    q17259: { h: "299a0f8c8d9a", text: "A vaccine trial eats up years, stage by stage: could you bear the years of stages?" },
    q17260: { h: "802e1ba2c180", text: "A biopharma experiment treats rounds of failure as normal: could you put up with rounds of failure?" },
    q17261: { h: "10e426281ac9", text: "Trust in an Ayurveda brand is built slowly over generations: could you bear the slowness of trust?" },
    q17262: { h: "e3f80188daf4", text: "The practice of a homeopathy clinic settles over years: would you count the years of practice?" },
    q17263: { h: "dd06725cced0", text: "Calibration of equipment comes round date after date: could you bear the return of the dates?" },
    q17264: { h: "44632de211ac", text: "The night queue of lab reports stretches until morning: could you put up with the night queue?" },
    q17265: { h: "50bd2b09080a", text: "Hospital payment gets stuck on insurance approval: could you bear being stuck on insurance?" },
    q17266: { h: "a186af4a374b", text: "The test of the edge of surgical tools has to be repeated again and again: could you put up with repeating the edge test?" },
    q17267: { h: "6c737e84b695", text: "The long night of hospital duty demands patience with patients: will you keep patience with patients?" },
    q17268: { h: "9db4b7f59ee6", text: "The line of telemedicine keeps cutting and connecting: could you bear the cutting line?" },
    q17269: { h: "09ed5351dfcc", text: "The trust of patients in medical tourism is built slowly: could you put up with the time it takes for patients to trust?" },
    q17270: { h: "00414d65d087", text: "Dental treatment goes on for months, sitting after sitting: could you bear the months of sittings?" },
    q17271: { h: "ac0b9be542ba", text: "The queue of an eye camp does not break until evening: could you put up with the camp queue?" },
    q17272: { h: "255102f3e34a", text: "The change from counselling shows over months of listening: could you bear the months of listening?" },
    q17273: { h: "ca363228d495", text: "The night bell of service to the elderly rings at any time: could you put up with the night bell?" },
    q17274: { h: "7262dd929432", text: "The family's trust in home nursing is built over weeks: could you bear the time it takes for the family to trust?" },
    q17275: { h: "bbba32abda0d", text: "In a traffic jam even the siren of an ambulance finds no way: could you put up with the agony of the jam?" },
    q17276: { h: "3b4a45bda88c", text: "The hour of shortage in a blood bank waits for donors: could you bear the hour of shortage?" },
    q17277: { h: "314d0686f21d", text: "The field result of farm biotech demands a crop cycle: would you count the result by the cycle?" },
    q17278: { h: "8cf411322fd6", text: "The scale-up of industrial biotech goes wrong again and again: could you put up with the scale-up going wrong?" },
    q17279: { h: "df78747dfa96", text: "The sampling trip of marine biotech waits for the weather: could you bear the weather for samples?" },
    q17280: { h: "f0576177a2df", text: "A tissue experiment demands watching day and night: could you put up with the nights of watching?" },
    q17281: { h: "129f917bf59d", text: "The ethical approval of a gene project runs long: could you bear the length of ethics approval?" },
    q17282: { h: "9a11808cb52f", text: "The queue for DNA reports moves over weeks: would you count the weeks for a report?" },
    q17283: { h: "b3ec7c7f2258", text: "The effect of bio-pesticide shows slowly, and the customer wants it fast: will you explain the slow effect?" },
    q17284: { h: "df561d2e653f", text: "Earthworm compost takes months to ripen and be fit to sell: could you bear the months of compost?" },
    q17285: { h: "8bc1c1b2e5bd", text: "The watch on cell storage is unbroken round the clock: will you keep the unbroken watch?" },
    q17286: { h: "2ff1471f91f5", text: "The results of stem-cell research stay years away: would you count the years of research?" },
    q17287: { h: "5d8153740c07", text: "On animal medicine rounds, credit spreads from village to village: could you put up with credit on the rounds?" },
    q17288: { h: "488bc614b5e3", text: "Inspections under the medical waste rules knock at the door again and again: could you bear the knocking of the rules?" },
    q18207: { h: "642947709e44", text: "A supplier of blister foil along with a medicine unit is the link for packing: would you think of the medicine-and-foil pair?" },
